    Differential Revision: https://phabricator.services.mozilla.com/D231098

diff --git a/mail/components/preferences/compose.js b/mail/components/preferences/compose.js
index 55f39d4ccd7..5237179c931 100644
--- a/mail/components/preferences/compose.js
+++ b/mail/components/preferences/compose.js
@@ -501,10 +501,12 @@ var gCloudFile = {
   makeButtonForProvider(provider) {
     const button = document.createXULElement("button");
     button.setAttribute("value", provider.type);
-    button.setAttribute(
-      "label",
-      this._strings.formatStringFromName("addProvider", [provider.displayName])
-    );
+    const label = this._strings.formatStringFromName("addProvider", [
+      provider.displayName,
+    ]);
+    button.setAttribute("label", label);
+    button.setAttribute("tooltiptext", label);
+    button.setAttribute("crop", "end");
     button.setAttribute(
       "oncommand",
       `gCloudFile.addCloudFileAccount("${provider.type}")`
